    <div class="checklist-heading"><div><h4>审查清单</h4><p>记录存在 ≠ 检查有效 ≠ 审查通过</p></div><div class="filter-group" role="group" aria-label="筛选审查清单"><button v-for="option in filters" :key="option.value" type="button" :aria-pressed="filter === option.value" @click="filter = option.value">{{ option.label }}</button></div></div>
    <ul class="review-checklist"><li v-for="item in visibleChecklist" :key="item.id"><span class="check-symbol" :class="item.status" aria-hidden="true">{{ item.status === 'BLOCKED' ? '!' : item.status === 'RECORDED' ? '↳' : '?' }}</span><div><h5>{{ item.title }} <span :class="['item-status', item.status]">{{ labels[item.status] }}</span></h5><p>{{ item.detail }}</p></div><button v-if="item.canNavigate" type="button" class="text-button" :disabled="!active" @click="emit('navigateWrite')">去核验 ↗</button></li></ul>
    <p v-if="visibleChecklist.length === 0" class="empty-state">当前筛选没有项目。这不代表所有审查门槛已通过。</p>
    <details class="review-action-panel"><summary><span>人工审查决定</span><span class="pending-badge">本地草稿 · 正式确认未接入</span></summary><div class="panel-content">
      <p>准备决定只检查本地表单，不产生正式审查。独立退回修改仍使用下方实际退回流程。</p>
      <form @submit.prevent="prepareReview" novalidate>
        <div class="form-grid"><label>审查范围<select v-model="scope" :disabled="!active"><option value="DOCUMENT">总稿</option><option v-if="sections.length" value="SECTION">单个章节</option></select></label><label>拟议决定<select v-model="decision" :disabled="!active"><option value="CONFIRM">确认（仅草稿）</option><option value="RETURN">退回（仅草稿）</option></select></label></div>
        <label v-if="scope === 'SECTION'" class="draft-label">已保存章节<select v-model="nodeId" :disabled="!active"><option value="">请选择章节</option><option v-for="section in sections" :key="section.nodeId" :value="section.nodeId">{{ section.title }}</option></select></label>
        <p v-if="!sections.length">未提供同版本已保存章节，不显示推测章节选项。</p><p v-else-if="scope === 'SECTION'">当前正文 DTO 没有章节修订标识；章节选择仅用于本地意见定位，不能提交正式决定。</p>
        <label class="draft-label">本地审查意见草稿<textarea v-model="opinion" rows="3" maxlength="16000" :disabled="!active" :aria-invalid="reviewAttempted && !opinion.trim()" placeholder="指出章节、问题或确认意见" /></label>
        <label class="draft-label">决定理由与依据<textarea v-model="reason" rows="2" maxlength="2000" :disabled="!active" :aria-invalid="reviewAttempted && !reason.trim()" placeholder="说明支持该决定的检查、来源与处理依据" /></label>
        <p class="draft-note">{{ opinion.length }} / 16000 · 仅保留在此页面，切换文稿或版本即清除。</p><ul v-if="reviewAttempted && reviewIssues.length" role="alert" class="validation-list"><li v-for="issue in reviewIssues" :key="issue">{{ issue }}</li></ul><button type="submit" :disabled="!active">检查草稿并预览决定</button>
      </form>
      <section v-if="reviewPreview" class="local-manifest" aria-label="本地决定预览"><h5>本地决定预览 · 尚未提交</h5><dl><dt>目标 / 拟议决定</dt><dd>{{ reviewPreview.target }} / {{ reviewPreview.decision === 'CONFIRM' ? '确认草稿' : '退回草稿' }}</dd><dt>固定正文版本</dt><dd>{{ reviewPreview.documentRevision }}</dd><dt>正文摘要</dt><dd>{{ reviewPreview.bodySha256 }}</dd><dt>记录修订 / 证据水位 / 问题水位</dt><dd>{{ reviewPreview.recordRevision }} / {{ reviewPreview.evidenceWatermark }} / {{ reviewPreview.issueWatermark }}</dd><dt>检查引用（未核验当前性）</dt><dd>{{ reviewPreview.checkIds.join('、') || '未提供' }}</dd><dt>意见</dt><dd>{{ reviewPreview.opinion }}</dd><dt>理由</dt><dd>{{ reviewPreview.reason }}</dd></dl><p v-if="decision === 'RETURN'">此草稿未分派责任人。实际退回须使用独立流程选择真实授权成员。</p></section>
      <section v-if="decision === 'RETURN'" class="local-manifest" aria-label="转到独立退回流程"><h5>继续实际退回修改</h5><p>独立流程退回整份已保存文稿，不是章节确认。仍须核查真实权限与条件、选择授权成员并单独确认，不会自动提交。</p><button type="button" :disabled="!active || dirty || !isCurrent" @click="navigateReturn()">打开独立退回流程（不复制草稿）</button><button type="button" :disabled="!returnHandoff" @click="navigateReturn(true)">使用本地意见与理由，打开退回流程</button><p>仅点击“使用本地意见与理由”才复制草稿；合并后须不超过 16000 字。不会覆盖已有未提交意见或结果未知的原请求。</p></section>
      <button type="button" disabled aria-describedby="review-unavailable">正式提交审查决定</button><p id="review-unavailable" class="disabled-reason">未接入：正式审查决定与当前检查有效性核验。不能用退回回执代替审查确认。</p>
    </div></details>
    <details class="review-action-panel"><summary><span>退回后的修订与重新提交</span><span class="pending-badge">本地整理 · 重新提交未接入</span></summary><div class="panel-content"><p>修改正文 → 保存新版本 → 专业复验 → 重新提交审查。仅有新版本不表示修改已完成。</p><p v-if="assignments == null">分派清单未载入。可在独立退回流程读取真实分派。</p><p v-else-if="resubmissionRows.length === 0">清单中没有此文稿的修改分派。</p>
      <article v-for="row in resubmissionRows" :key="row.assignmentId" class="assignment-row"><strong>{{ row.changed ? '已存在不同正文版本，仍需复验' : '尚未观察到新正文版本' }}</strong><p>{{ row.reason }}</p><dl><dt>原退回正文</dt><dd>{{ row.originalRevision }}</dd><dt>当前读取正文</dt><dd>{{ row.currentRevision }}</dd></dl><p v-if="!row.matchesObservedCurrent">分派回读中的当前版本与本页不一致，需重新读取后再核验。</p><p>{{ row.checkCount }} 个当前检查引用；缺少当前有效性、覆盖范围及问题解决证明。</p></article>
      <label class="draft-label">修订说明（本地）<textarea v-model="revisionNote" rows="2" maxlength="2000" :disabled="!active" placeholder="说明本次修订如何回应退回意见" /></label><button type="button" :disabled="!active" @click="prepareResubmission">整理重新提交摘要</button><p v-if="resubmissionAttempted && !revisionNote.trim()" role="alert">请先填写修订说明。</p><section v-if="resubmissionPrepared" class="local-manifest"><h5>重新提交摘要 · 本地，未提交</h5><p>{{ revisionNote }}</p><p>当前版本：{{ snapshot.document_revision }}</p><p>{{ resubmissionRows.length ? '以上原版本与当前版本对照仅用于复核。' : '原退回版本和分派未载入，无法确认修订对应关系。' }}</p><ul><li>仍缺当前检查有效性与完整覆盖核验</li><li>仍缺阻断问题及失效意见处理结果</li><li>仍缺正式重新提交接口与回读结果</li></ul></section><div class="action-row"><button type="button" :disabled="!active" @click="emit('navigateWrite')">返回撰写与复验</button><button type="button" disabled aria-describedby="resubmit-unavailable">重新提交审查</button></div><p id="resubmit-unavailable" class="disabled-reason">未接入：当前检查核验器与正式重新提交。不会因保存新正文自动改为待审。</p></div></details>
    <details class="review-action-panel signing-panel"><summary><span>正式签发</span><span class="pending-badge">流程预览 · 不执行签发</span></summary><div class="panel-content"><p>以下仅预览签发流程，不创建认证挑战、回执或签名。选择步骤不表示该步骤已完成。</p>
      <nav class="step-tabs" aria-label="签发流程预览步骤"><button v-for="(step, index) in signingSteps" :key="step" type="button" :aria-pressed="signStep === index" @click="signStep = index">{{ index + 1 }}. {{ step }}</button></nav>
      <section v-if="signStep === 0"><h5>1. 准备用途与版本</h5><label class="draft-label">签发用途（本地）<input v-model="purpose" :disabled="!active" maxlength="2000" placeholder="说明本次签发用途，不替代服务端用途策略" /></label><button type="button" :disabled="!active" @click="prepareSigning">核对本地签发清单</button><ul v-if="signAttempted && signingIssues.length" role="alert"><li v-for="issue in signingIssues" :key="issue">{{ issue }}</li></ul></section>
      <section v-else-if="signStep === 1"><h5>2. 版本与清单复核</h5><dl class="local-manifest"><dt>用途</dt><dd>{{ purpose.trim() || '尚未填写' }}</dd><dt>固定版本</dt><dd>{{ snapshot.document_revision }}</dd><dt>正文摘要</dt><dd>{{ snapshot.body.sha256 }}</dd><dt>证据 / 问题水位</dt><dd>{{ snapshot.evidence_watermark }} / {{ snapshot.issue_watermark }}</dd><dt>签发策略</dt><dd>未接入，不能推测策略版本或签发资格</dd></dl><label><input v-model="manifestAcknowledged" type="checkbox" :disabled="!active || !purpose.trim()" /> 我已复核此本地清单（不是签发确认）</label><button type="button" :disabled="!manifestAcknowledged" @click="signStep = 2">查看身份核验步骤</button></section>
      <section v-else-if="signStep === 2"><h5>3. 身份核验（未执行）</h5><p>实际流程需由服务端发起并验证绑定此文稿、版本、用途和策略的挑战。本页没有发起登录或取得认证回执。</p><button type="button" disabled>开始身份核验 · 未接入</button><button type="button" @click="signStep = 3">查看确认界面示意</button></section>
      <section v-else-if="signStep === 3"><h5>4. 最终确认（界面示意）</h5><p>拟签发用途：{{ purpose.trim() || '未填写' }}；正文版本：{{ snapshot.document_revision }}</p><label><input v-model="confirmationPreview" type="checkbox" :disabled="!active" /> 我理解签发会固定版本与人员信息（仅本地演练，不表示已授权签发）</label><p>服务端门槛与身份回执均未取得，即使勾选也不能提交。</p><button type="button" @click="signStep = 4">查看等待与异常提示示意</button></section>
      <section v-else><h5>5. 等待与异常提示（模拟状态，不是真实操作）</h5><label class="draft-label">预览显示状态<select v-model="signScenario"><option value="UNAVAILABLE">服务未接入</option><option value="PENDING">等待回执的界面示意</option><option value="ERROR">请求失败的界面示意</option></select></label><p role="status" class="local-manifest">{{ signScenario === 'PENDING' ? '模拟等待：若真实签发结果未知，应查询原操作回执，不重复创建签发。当前没有真实操作标识。' : signScenario === 'ERROR' ? '模拟异常：保留原版本与用途，核查错误和最新门槛后再决定下一步。本页没有发生签发请求失败。' : '真实状态：签发服务未接入，尚未发出任何请求。' }}</p></section>
      <button type="button" disabled aria-describedby="signing-unavailable">正式确认并签发</button><p id="signing-unavailable" class="disabled-reason">未接入：签发就绪度、身份核验与正式签发提交。未生成身份回执、签名或签发成功状态。</p></div></details>
  </section>
</template>
<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { reviewWorkspaceModel, savedReviewSections, localReviewIssues, localReviewPreview, revisionResubmissionRows, localReturnHandoff } from '../../api/medical/document-review-workspace'
import type { ReviewWorkspaceInput, ReviewChecklistItem, LocalReviewDraft, LocalReturnHandoff } from '../../api/medical/document-review-workspace'
const props = withDefaults(defineProps<ReviewWorkspaceInput>(), { dirty: false, isCurrent: false, active: true })
const emit = defineEmits<{ navigateWrite: [sectionId?: string]; navigateReturn: [handoff?: LocalReturnHandoff] }>()
const model = computed(() => reviewWorkspaceModel(props))
const opinion = ref('')
const filter = ref<'ALL' | 'BLOCKED' | 'UNKNOWN'>('ALL')
const filters = [{ value: 'ALL', label: '全部' }, { value: 'BLOCKED', label: '已知阻碍' }, { value: 'UNKNOWN', label: '待核验' }] as const
const labels: Record<ReviewChecklistItem['status'], string> = { RECORDED: '已读取', BLOCKED: '需处理', UNKNOWN: '待核验' }
const visibleChecklist = computed(() => model.value.checklist.filter(item => filter.value === 'ALL' || item.status === filter.value))
const scope = ref<LocalReviewDraft['scope']>('DOCUMENT'), nodeId = ref(''), decision = ref<LocalReviewDraft['decision']>('CONFIRM'), reason = ref('')
const reviewAttempted = ref(false), reviewPreview = ref<ReturnType<typeof localReviewPreview>>(null)
const sections = computed(() => savedReviewSections(props))
const reviewDraft = computed<LocalReviewDraft>(() => ({ scope: scope.value, nodeId: nodeId.value, decision: decision.value, opinion: opinion.value, reason: reason.value }))
const reviewIssues = computed(() => localReviewIssues(props, reviewDraft.value))
function prepareReview() { reviewAttempted.value = true; reviewPreview.value = localReviewPreview(props, reviewDraft.value) }
const returnHandoff = computed(() => localReturnHandoff(props, reviewDraft.value))
function navigateReturn(copyDraft = false) {
  if (!props.active || props.dirty || !props.isCurrent) return
  if (copyDraft) { if (returnHandoff.value) emit('navigateReturn', returnHandoff.value) }
  else emit('navigateReturn')
}
const resubmissionRows = computed(() => revisionResubmissionRows(props)), revisionNote = ref(''), resubmissionAttempted = ref(false), resubmissionPrepared = ref(false)
function prepareResubmission() { resubmissionAttempted.value = true; resubmissionPrepared.value = props.active && !!revisionNote.value.trim() }
const signingSteps = ['准备用途', '版本清单', '身份核验', '确认示意', '等待与异常']
const signStep = ref(0), purpose = ref(''), signAttempted = ref(false), manifestAcknowledged = ref(false), confirmationPreview = ref(false), signScenario = ref<'UNAVAILABLE' | 'PENDING' | 'ERROR'>('UNAVAILABLE')
const signingIssues = computed(() => [...(!purpose.value.trim() ? ['请填写签发用途。'] : []), ...(!props.active || props.dirty || !props.isCurrent ? ['请先处理草稿或当前版本变化。'] : [])])
function prepareSigning() { signAttempted.value = true; if (!signingIssues.value.length) signStep.value = 1 }
watch([opinion, reason, scope, nodeId, decision], () => { reviewPreview.value = null }, { flush: 'sync' })
watch(revisionNote, () => { resubmissionPrepared.value = false }, { flush: 'sync' })
watch(purpose, () => { manifestAcknowledged.value = false; confirmationPreview.value = false }, { flush: 'sync' })
watch(() => [props.snapshot.project_id, props.snapshot.document_id, props.snapshot.document_revision, props.snapshot.revision, props.snapshot.body.sha256, props.snapshot.evidence_watermark, props.snapshot.issue_watermark, props.returnContextKey], () => {
  opinion.value = ''; reason.value = ''; scope.value = 'DOCUMENT'; nodeId.value = ''; decision.value = 'CONFIRM'; reviewAttempted.value = false; reviewPreview.value = null; filter.value = 'ALL'
  revisionNote.value = ''; resubmissionAttempted.value = false; resubmissionPrepared.value = false
  purpose.value = ''; signStep.value = 0; signAttempted.value = false; manifestAcknowledged.value = false; confirmationPreview.value = false; signScenario.value = 'UNAVAILABLE'
}, { flush: 'sync' })
watch(() => [props.active, props.dirty, props.isCurrent, props.savedBody], () => { reviewPreview.value = null; manifestAcknowledged.value = false; confirmationPreview.value = false; resubmissionPrepared.value = false }, { flush: 'sync' })

</script>
